{
  "name": "opencode-ops",
  "version": "1.2.0",
  "description": "OpenCode Ops — SSH sessions, local terminals, dashboard, multi-instance. All-in-one operations plugin.",
  "type": "module",
  "main": "src/index.ts",
  "files": [
    "src"
  ],
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target node --external @opencode-ai/plugin --external ssh-config",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "dependencies": {
    "@noble/hashes": "^2.2.0",
    "@opencode-ai/plugin": "^1.4.0",
    "@opencode-ai/sdk": "^1.4.0",
    "fflate": "^0.8.2",
    "ssh-config": "^5.0.3",
    "tweetnacl": "^1.0.3"
  },
  "devDependencies": {
    "@types/bun": "^1.3.0",
    "typescript": "^5.9.0"
  },
  "peerDependencies": {
    "bun": ">=1.1.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ssh",
    "terminal",
    "ops",
    "dashboard",
    "multi-session"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/asychin/opencode-ops"
  }
}
